  Ltac c8ifyF H := lazymatch type of H with rw_cells _ ?m ?A ?cs =>
    let rec go pre l := lazymatch l with
       | CB 8 ?b :: ?post => apply (w4s_cb8_c8 _ m A pre post b) in H; cbn [app] in H
       | ?c :: ?l' => go constr:(pre ++ [c]) l'
       | [] => fail end in
    go constr:(@nil cell) cs end.
  Ltac absj H := repeat match type of H with context [le_bytes_to_word ?b] =>
    let w := fresh "wj" in set (w := le_bytes_to_word b) in H; clearbody w end.
  Ltac retlit := lazymatch goal with |- context [ret_pc (Z_to_bv 64 ?n)] =>
    replace (ret_pc (Z_to_bv 64 n)) with (Z_to_bv 64 n) by (symmetry; apply ret_pc_even; [lia| reflexivity]) end.
  Ltac w4pack := split; [eexists; split; eassumption|];
    repeat (split; [first [eassumption | reflexivity | eexists; eassumption]|]); first [eassumption | eexists; eassumption].

