  Lemma w4sf_bitcall : forall mm m1 sa sb bd4 bd4', W4SF' mm sa sb bd4 ->
    munch [(SPF - ABIT_INIT_STACK, SPF); (SPF + 240, SPF + 240 + 40)] mm m1 -> wmono asegs mm m1 ->
    mem_inv asegs m1 -> stk asegs m1 lo SPF -> rw_cells asegs m1 (SPF + 240) bd4' -> cells_size bd4' = 40%nat ->
    0 < n -> 6 <= dcap -> W4SF' m1 sa sb bd4'.
